INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Машҳуд ва тавсияҳои техникӣ барои танзими дурусти фосилаи қаторӣ дар заҳрати ҷинсфенкурр (оромӣ). Ин мақола принсипҳои амалиягӣ ва меъёрҳои стандартиро барои фермерҳо шарҳ медиҳад.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
