INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: зарурати истифодаи озуи қатқалавӣ дар парвариши боқорӣ</h2>\n<p>Боқорӣ яке аз сабзиёти талаботи баланд буда, ҳассосияти зиёде ба фишори обӣ ва гармии ҳаво дорад. Азбаски системаи решаи боқорӣ асосан сатҳӣ ва чӯқи нест, расониши доимӣ ва якхелаи об ба минтақаи решагӣ (Root Zone) ҳаётӣ аст. Усулҳои озуи сатҳӣ одатан боиси тар кардани зиёди сатҳи хок ва буҳоршавии шадиди об мегарданд, ки барои намудиҳои ҳассос зарарнок аст. Баръакс, системаҳои нави ва қатқалавӣ орои обро ба шакли қатқаҳо ва мустақиман наздики решаҳо ҷоҳ мекунад. Ин раванд на танҳо шустани (Leaching) моддаҳои ғизоиро аз хокро ба ҳадди ақалл мерасонад, балки намро дар сатҳи ҳарофарӣ нигоҳ медорад. Дар ин мақола, бо ягонаҳои техникии ҷобаҷогузорӣ, танзимотҳои ҳидролиқӣ ва барориши замони барои иҷрои муваффақонаи ин система дар деҳқонӣҳои боқорӣ шинос мешавед, ки метавонад нархи истеҳсоли шуморо коҳиш ва самараноеҳоро зиёд кунад.</p>\n\n\n<h2>Интихоби усули партофтан ва беҳтаркунии ҷобаҷогузории системаи озу</h2>\n<p>Муваффақият дар озуи қатқалавии боқорӣ, мустақиман ба дақиқӣ дар ҷобаҷогузории ибтидоӣ вобаста аст. Боқорӣ одатан бо усулҳои сатрӣ партофта мешавад. Фосилаи стандартӣ байни сатрҳо (Row Spacing), ки ба он фосилаи сатр ё кушодиҳ мегӯянд, вобаста ба намуди иқлим ва зичии партов, одатан байни 40 то 50 сантиметр муайян мегардад. Ин фосила бояд тавре ҳисоб карда шавад, ки навҳои тирӣ фавран зери ё дар ҷони баргҳо ҷойгир шаванд, то фарогирии беҳтарини намро бароарзад. Барои кам кардани миқдори гӯлҳои ғайрифароғатонӣ байни сатрҳо ва осонкунии кор барои гурӯҳи партовиш ва харидорӣ, баъзан фосилаи сатрҳоро то 60 сантиметр зиёд мекунанд, аммо дар ин ҳолат бояд даромади қатқалавонҳоро тағйирёбанда (Variable) ба назар гиред ё аз қатқалавонҳое бо даромади баландтар истифода баред, то фарогирии пурраи ҷойи партофтан таъмин гардад. Истифодаи плёнкаи пластикии сиёҳ ё сабз дар атрофи нави тирӣ низ метавонад ба пешгирии парвариши гӯлҳои ғайрифароғатонӣ ва назорати беҳтартари ҳарорати хок кӯмак расонад. Ин намоиши комбинатсионӣ боиси мешавад, ки энергияи баргҳо барои рушди қисми ҳавоӣ ва истеҳсоли маҳсулот сарф шавад, на дар рақобат бо гӯлҳои зарарнок.</p>\n\n\n<h3>Муайян кардани фосилаи қатқалавонҳо ва миқдори онҳо дар ҳар сатр</h3>\n<p>Саволи маъмул дар бораи озуи қатқалавии боқорӣ ин аст, ки фосилаи мувофиқ байни қатқалавонҳо чӣ қадар аст? Барои боқорӣ, ба сабаби решаҳои сатҳӣ ва рушди тез, истифода аз қатқалавонҳое бо даромади 2 литр дар соат ва фосилаи 20 то 25 сантиметрӣ идеалӣ аст. Ин ҷобаҷогузорӣ кафолат медиҳад, ки нам ба шакли якхела дар тӯли сабуки ва реша паҳн шавад ва аз пайдоиши лакаҳои хушк дар хок пешгирӣ кунад. Инчунин бояд диққат дод, ки ибтиҳоди ҳар нави тирӣ нуқтаи ҳассоси фишор аст. Агар нави хеле тӯл дароварда бошад, коҳиши фишорро дар охири он бояд бо интихоби қатқалавонҳое бо даромади мувофиқ ё истифода аз пасомандатанзимкунандаи фишор (backpressure) танзим кард. Барои деҳқонӣҳо бо хоки вазнин, шояд лозим шавад, ки фосилаи қатқалавонҳо камтар карда шавад (масалан, 15 сантиметр), то нам бо суръати бештар ба решаҳо расад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-اسفناج-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت اسفناج با آبیاری قطره‌ای - تصویر 1"/><figcaption>усулҳои партов озуи қатқалавӣ тартиби озу боқорӣ</figcaption></figure>\n\n<h2>Барориши замони озуи қатқалавии боқорӣ</h2>\n<p>Мидиркунии замони озу муҳимтарин қисми муҳандисии ин раванд аст. Боқорӣ дар марҳилаҳои гуногуни рушд, талаботи обии гуногун дорад ва ноодиёни ба ин каҷи ҳаётӣ метавонад боиси шур шудан ё оҳиста шудани рушд гардад. Яке барориши стандартӣ барои иҷрои дурусти озуи қатқалавии боқорӣ дар ҷадвали зеро оварда шудааст, ки асосан шартҳои боғиро дар бар мегирад:</p>\n\n\n<table>\n    <tr>\n        <th>Марҳилаи рушд</th>\n        <th>Муддати озуи рӯзона</th>\n        <th>Шумораи борҳо озу</th>\n        <th>Нуқтаҳои асосии иҷроӣ</th>\n    </tr>\n    <tr>\n        <td>Сабзидан то пайдоиши 2 барг</td>\n        <td>15 то 20 дақиқа</td>\n        <td>Рӯзона</td>\n        <td>Нигоҳ доштани нами сатҳӣ барои шикастани токҳо ва пешгирии хушк шудани ҷойи партофтан</td>\n    </tr>\n    <tr>\n        <td>Рушди тез (3 то 4 ҳафта)</td>\n        <td>25 то 35 дақиқа</td>\n        <td>Ҳар ду рӯз як маротиба</td>\n        <td>Баланд шудани қубури хок обнокондашуда ва дастрасии реша ба қабатҳои амиқтар</td>\n    </tr>\n    <tr>\n        <td>Аз нурафаррезигӣ то пухтоналии пурра</td>\n        <td>40 то 50 дақиқа</td>\n        <td>Ҳар рӯз ё ҳар ду рӯз</td>\n        <td>Ҳифзи намнокӣ барои пешгирии вайроншавӣ ва афзудани ҳаҷми баргҳо</td>\n    </tr>\n    <tr>\n        <td>Марҳакаи ҷамъоварӣ ва ғунӣи оянда</td>\n        <td>30 то 40 дақиқа</td>\n        <td>Ҳар рӯз</td>\n        <td>Беҳтар аст обиро дар соатҳои хунуки рӯз анҷом додан ва назорати дақиқи намнокӣ</td>\n    </tr>\n</table>\n\n<p>Дарёфти минтақаҳои хокӣ ва ҳавоӣ ба ин ҷадвал таъсири мустақим дорад. Масалан, дар минтақаҳои гарм бо хокҳои риғавӣ, баъзан зарур аст обиро кӯтоҳтар, аммо бо шиддати бештар анҷом додан. Инчунин, барои идоракунии дақиқтар, истифодаи ченкунии намнокӣ-и хок тавсия мешавад. Гарчанде ки мавзӯи мушаххаси ... <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D9%85%D9%84%D9%88%D9%86-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Ҳаҷми ғунӣи хурмои дар гектар</a> Ба аспараг бевосита дахор надорад, аммо асосҳои умумии идоракунии намнокӣ-и хок дар сабзавоти бо баргҳои васеъ ва ниёзи баланд ба моддаҳои майданӣ хеле монанд аст. Фаҳмиши ин монандиҳо ба деҳқон кӯмак мекунад, то моделшавии иктилофиро барои сабзавоти гуногун яксабт кунад ва аз тажрибаҳои монанд фоида барад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-اسفناج-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت اسفناج با آبیاری قطره‌ای - تصویر 2"/><figcaption>Usuli kashishi vortib obinoi tufoni asparga</figcaption></figure>\n\n<h2>Мавороти амалӣ ва идоракунии системаи навъчии тавсиф</h2>\n<ul>\n    <li><strong>Филтркунандагии қавӣ:</strong> Аспараг тез рӯй додан мерезад ва одаки обиро маҳкам карда метавонад. Мувофиқи ченкунии филтрҳои дискӣ (Screen) бо тармои 100-200 микрон истифода баред. Пуркунӣ ва тозагӣ-и филтрҳо калиди устувории системаи шумост.</li>\n    <li><strong>Санитарияи система:</strong> Пеш аз насб кардани навориҳо, системаро бо об таъмин кунед, то ки боварӣ ҳосил кунед, ки дар пайвандҳо (коннекторҳо) часпидан ё рутубат нест. Фишори воридотӣ ба система бояд байни 1 то 2 бар бошад.</li>\n    <li><strong>Тарим дар ҳамсарошӣ бо суғорӣ:</strong> Аз бободи асосии навориҳо дар шакли бамбир истифода кунед ва моддаҳои омадакунакиро тавассути системаи суғорӣ (Fertigation) ворид кунед. Ин кор ба ҷазби зудтари моддаҳои ғизоӣ оварда мерасонад. Барои хабар доштани ҳалшудаҳои тавсияшуда, шумо метавонед таҳқиқот <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%AE%D8%B1%D8%A8%D8%B2%D9%87-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Микдори бободи хушмелон ба ҳектар</a> барои муқоисаи ниёз ба моддаҳои омадакунак дигар намудҳои сабзиҳо анҷом диҳед, гарчанде ки аспанаки ба потазиюм камтар ниёз дорад.</li>\n    <li><strong>Идоракунии намоиши мавсумӣ:</strong> Баъд аз ҷамъоварии асосӣ, навориҳоро тоза кунед ва дар ҷои нав барои насби дигар ҷойгир кунед. Агар шумо аз навориҳои сифатнок бо умри корӣ баланд истифода бурда бошед, метавонед дар як мавсум 2 то 3 намоишро кунед. Барои идоракунии намоиш, шумо метавонед хизматрасониҳои навориҳо барои муқоиса кардан ва интихоби беҳтарин вариант барои харидорӣ ё иҷора.</li>\n</ul>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<ol>\n    <li><strong>Оё навори бамбир барои тарими сабзиҳо кофӣ аст?</strong><br>Бале, навориҳо бо қубурҳои мувофиқ барои сабзиҳои ҳассос аз қабили аспанаки кофӣ аст. Беҳтар аст аз бренدهое истифода баред, ки қабати UV-устодор доранд, то муқовимат бар зидди радикалҳои озод ва нурҳои офтоб боло равад.</li>\n    <li><strong>Кай беҳтарин вақти насби навори бамбир аст?</strong><br>Навориҳоро маҳз ҳамзамон бо насби бободи бачаҳо дар замин ҷойгир кунед, то ки решаҳои навзод аз оғози кор бо минтақаи хуташдар дар ҳамсарошӣ бошанд.</li>\n    <li><strong>Агар навори бамбир шадид шаванд, чӣ кор бояд кард?</strong><br>Шадид шудани навориҳо аломати аз даст додани шаффойя мебошад. Бояд навориҳоро хориҷ карда, тоза намуд ва дар омехтаи мувофиқ нигоҳ дошт, то барои намоиши минбаъда истифодаи онҳо имкон дошта бошад. Дар сурати парёх шудан, аз часби махсус барои навориҳо истифода баред.</li>\n    <li><strong>Оё дар заминҳои шикофдор аз бамбирҳо истифода бурдан мумкин аст?</strong><br>Бале, аммо лозим аст, ки манифолдро танзим кунед, то ки фишор аз шикоф кам шавад ва дар охирин навориҳо фишори иловагӣ пайдо нашавад.</li>\n</ol>\n\n<h2>Хулоса: Роҳ ба натиҷаҳои беҳтар дар тарими аспанаки</h2>\n<p>Истифодаи системаи обори каҳқаӣ ва намунаи қарға дар каҳраи чигарашӯӣ боз як имконоти лўкшӣ нест, балки як зарурати иқтисодӣ ва техникӣ аст. Бо кам кардани истифодаи об, беҳтар шудани ҷавонии гиёҳҳо, пешгирӣ аз беморҳои қарчавии ба омад аз шитоб кардани баргҳо ва имкони дастгирии дақиқ, кишовар метавонад ба муваҷҷияти баландтар бирасад. Калиди муваффақият дар ҷойест, ки даврони пурра аз харидани намуна, насб, филтрсия, дастгири ва идоракунии миқдорро ҳамчун як системаи якҷоя дар назар дошта бошед. Барои оғоз ин роҳи тартибида, таҳқиқот манбаҳои ихтисосӣ ва интихоби брендҳои ҷисми намунаи қарға муҳимтар буд. Обори каҳқаӣ чигарашӯӣ, агар бо дақиқӣ ва нақшагузории дуруст ҳамроҳ бошад, сарсозиест, ки дар муддати кӯтоҳ толифҳоро ба муваҷҷияти муносиб табдил меояд.</p>\n\n<p><strong>Моддалоти пайваста:</strong> Принсипҳои муқаррарии ҳосил дар ҳектар,  <a href="https://navar-abyari.ir/barley-seed-rate-per-hectare-iraq/">Бичори жав дар ҳектари Эрон</a></p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-اسفناج-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت اسفناج با آبیاری قطره‌ای - تصویر 3"/><figcaption>planting methods drip crop irrigation schedule чигарашӯӣ</figcaption></figure>\n<p><strong>Моддалоти пайваста:</strong> <a href="https://navar-abyari.ir/%D8%AA%D9%86%D8%A7%DA%98-%D9%82%D8%B5%DB%8C%D9%84-%D8%AC%D9%88-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D8AAD986D8A7DA98 D982D8B5DB8CD984 D8ACD988 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a></p>','Мукамоиди пурраи парвариши аспараг бо обориш пуррақатор ва навареи TIP','Кӯпоки сабзи (аспанҷ) яке аз мавҷудияти мушкил аст, ки идоракунии боэҳтиромонаи захираҳои об ва хокро талаб мекунад. Истифодаи технологияи навори ғарди (типӣ) ва пилҳо (дамлатси) дақиқ калиди муваффақият дар истеҳсоли ҳосили сабзавот бо сифати баланд ва камтарин хароҷоти об мебошад. Дар ин дастурамози фаҳмондакунанда аз интихоби ҷузъи сохтаи дуруст то ҷадвали тайёркунии оборӣ ва партовкуни пуркунак бо система, ҳамаи хусусиятҳои муҳимро барои шумо мушаххас кардем. Агар шумо дар ҷустуҷӯи зиёд кардани ҳосили ҳар гектар бошед, ин мақола меъёрҳо ва усулҳои амалӣ лозимаро пешниҳод мекунад, то ба натиҷаи мехоҳадагӣ расед ва самаранокии майдони худро ба авҷ баррасед.','publish','closed','closed','mulimoiyidi-aspargh-oborish-nawari-tip',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
